    private WormBreedAnimation() {
    }

    /** The channel's value at {@code t} seconds (linear between keyframes) into {@code out}; false if no channel. */
    static boolean sample(float[] times, float[] values, float t, float[] out) {
        if (times == null) {
            return false;
        }
        int last = times.length - 1;
        if (t <= times[0]) {
            System.arraycopy(values, 0, out, 0, 3);
            return true;
        }
        if (t >= times[last]) {
            System.arraycopy(values, last * 3, out, 0, 3);
            return true;
        }
        int k = 0;
        while (times[k + 1] < t) {
            k++;
        }
        float f = (t - times[k]) / (times[k + 1] - times[k]);
        for (int c = 0; c < 3; c++) {
            out[c] = values[k * 3 + c] + (values[(k + 1) * 3 + c] - values[k * 3 + c]) * f;
        }
        return true;
    }
